#pragma once
namespace iah {
inline const char* renderBridgeSettingsPage(){return R"IAH(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>iPhone Agent Bridge</title><style>html{color-scheme:light dark;font:17px system-ui}body{max-width:540px;margin:36px auto;padding:0 20px}h1{font-size:25px}label{display:block;margin:20px 0 7px}input,button{box-sizing:border-box;font:inherit;padding:12px;width:100%;border:1px solid #aaa;border-radius:10px}button{margin-top:22px;cursor:pointer}p{line-height:1.5;overflow-wrap:anywhere}code{overflow-wrap:anywhere}#status{white-space:pre-wrap}a{display:block;margin-top:18px}</style></head><body><h1>iPhone Agent Bridge</h1><p id="status" role="status"></p><form id="settings" hidden><label id="hostLabel" for="hostname"></label><input id="hostname" required pattern="[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?" maxlength="63" autocomplete="off" autocapitalize="none" spellcheck="false"><p id="address"></p><button id="save"></button></form><a id="next" hidden></a><script>
const messages={"en":["Bridge settings","Connecting…","Local device name","Save","Saved.","Saved. The bridge is restarting. Open its new address shortly.","Stop the current task before changing settings.","Connection failed.","Open bridge settings"],"zh-Hans":["桥接器设置","正在连接…","局域网设备名","保存","已保存。","已保存，桥接器正在重启。稍后打开新地址。","请先停止当前任务，再修改设置。","连接失败。","打开桥接器设置"],"zh-Hant":["橋接器設定","正在連線…","區域網路裝置名稱","儲存","已儲存。","已儲存，橋接器正在重新啟動。稍後開啟新位址。","請先停止目前的任務，再修改設定。","連線失敗。","開啟橋接器設定"],"ja":["ブリッジ設定","接続中…","ローカルデバイス名","保存","保存しました。","保存しました。ブリッジの再起動後、新しいアドレスを開いてください。","設定を変更する前に現在のタスクを停止してください。","接続できませんでした。","ブリッジ設定を開く"],"ru":["Настройки моста","Подключение…","Имя устройства в локальной сети","Сохранить","Сохранено.","Сохранено. Мост перезапускается. Затем откройте новый адрес.","Остановите текущую задачу перед изменением настроек.","Не удалось подключиться.","Открыть настройки моста"],"de":["Bridge-Einstellungen","Verbindung wird hergestellt…","Lokaler Gerätename","Speichern","Gespeichert.","Gespeichert. Die Bridge startet neu. Öffne anschließend die neue Adresse.","Beende die laufende Aufgabe, bevor du Einstellungen änderst.","Verbindung fehlgeschlagen.","Bridge-Einstellungen öffnen"],"fr":["Réglages du pont","Connexion…","Nom local de l’appareil","Enregistrer","Enregistré.","Enregistré. Le pont redémarre. Ouvrez ensuite sa nouvelle adresse.","Arrêtez la tâche en cours avant de modifier les réglages.","Échec de la connexion.","Ouvrir les réglages du pont"],"es":["Ajustes del puente","Conectando…","Nombre local del dispositivo","Guardar","Guardado.","Guardado. El puente se está reiniciando. Después, abre la nueva dirección.","Detén la tarea actual antes de cambiar los ajustes.","No se pudo conectar.","Abrir ajustes del puente"]};
const locale=(navigator.languages||[navigator.language||'en'])[0],language=/^zh/i.test(locale)?(/Hant|TW|HK|MO/i.test(locale)?'zh-Hant':'zh-Hans'):(locale.split('-')[0] in messages?locale.split('-')[0]:'en'),m=messages[language],el=id=>document.getElementById(id);document.documentElement.lang=language;document.title=m[0]+' · iPhone Agent Bridge';
for(const [id,index] of Object.entries({status:1,hostLabel:2,save:3,next:8}))el(id).textContent=m[index];
let token='',clientId='';try{token=sessionStorage.getItem('iah-manager-token')||'';clientId=localStorage.getItem('iah-manager-client')||'';}catch{}
if(!/^[a-z0-9-]{1,80}$/.test(clientId)){clientId='manager-'+Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');try{localStorage.setItem('iah-manager-client',clientId);}catch{}}
async function request(path,method='GET',body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(path,{method,cache:'no-store',signal:controller.signal,headers:{'X-Harness-Window':'1',...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok)throw Object.assign(new Error(value.error||m[7]),{status:response.status});return value;}finally{clearTimeout(timer);}}
function errorMessage(error){return error.message==='board_busy'?m[6]:m[7];}
function show(value){el('settings').hidden=false;el('hostname').value=value.hostname;el('address').textContent='http://'+value.hostname+'.local';el('status').textContent='';}
async function connect(){if(token){try{show(await request('/v1/settings'));return;}catch(error){if(error.status!==401)throw error;token='';try{sessionStorage.removeItem('iah-manager-token');}catch{}}}const paired=await request('/v1/pair','POST',{clientId});token=paired.token;try{sessionStorage.setItem('iah-manager-token',token);}catch{}show(await request('/v1/settings'));}
el('settings').onsubmit=async event=>{event.preventDefault();el('save').disabled=true;try{const result=await request('/v1/settings','POST',{hostname:el('hostname').value.trim().toLowerCase()});show(result);el('status').textContent=m[result.restartRequired?5:4];if(result.restartRequired){el('save').hidden=true;el('hostname').disabled=true;el('next').href=result.newURL+'/settings';el('next').hidden=false;}}catch(error){el('status').textContent=errorMessage(error);}finally{el('save').disabled=false;}};
connect().catch(error=>{el('status').textContent=errorMessage(error);});
</script></body></html>)IAH";}
}
